def solve(base, relative):
    if relative.startswith('/') or '\\' in relative:
        return None
    parts = []
    for part in base.split('/'):
        if part:
            parts.append(part)
    for part in relative.split('/'):
        if not part or part == '.':
            continue
        if part == '..':
            if not parts:
                return None
            parts.pop()
        else:
            parts.append(part)
    return '/' + '/'.join(parts)

