def solve(base, relative):
    if relative.startswith('/') or '\\' in relative:
        return None
    parts = []
    if base != '/':
        for part in base.split('/'):
            if part:
                parts.append(part)
    floor = len(parts)
    for part in relative.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if len(parts) <= floor:
                return None
            parts.pop()
        else:
            parts.append(part)
    result = '/' + '/'.join(parts)
    return result

